const gcd = (a, b) => (b ? gcd(b, a % b) : a);

// القطعة (تبدأ من 1) عند الفتحة رقم k من الرأس، لسكن عدد قطعه n
// الفتحة k تقع على الحلقة 4k+2، والحلقة ri تأخذ القطعة (ri % n) + 1
const gapPiece = (k, n) => ((4 * k + 2) % n) + 1;
const gapRing = (k) => 4 * k + 2;
const gapPeriod = (n) => n / gcd(n, 4);
const R_FACTOR = 0.8; // نصف قطر الخطر ÷ السماكة (تقدير بين 0.77 و0.81)
const hazardRadius = (thickness) => R_FACTOR * thickness;
const dist = (a, b) => Math.hypot(a[0] - b[0], a[1] - b[1]);
// الفتحة تفتح إذا كان التباعد بين النقطتين أكبر من ضعف نصف قطر الخطر
const gapPassable = (spacing, thickness) => spacing > 2 * hazardRadius(thickness);
const survives = (head, points, thickness) => points.every((p) => dist(head, p) > hazardRadius(thickness));
const pathSurvives = (path, points, thickness) => path.every((h) => survives(h, points, thickness));
// الحلقة ri فيها فتحة إذا ri % 4 == 2 (نفس 4k+2)
// "passable": دائرة فقط على الفتحات السالكة (تباعد > 2×نصف قطر الخطر) | "largest": أكبر فجوة فقط | "all": كل حلقات 4k+2
const GAP_MODE = "all"; // "passable" | "largest" | "all"
// ===== معايرة: لكل عدد قطع n ولكل دورة (n حلقات من الرأس) تحدّد بنفسك أي الحلقات تُلوَّن =====
const WZ_CAL_KEY = "wzGapCal_v2";
// جدول ثابت يُملأ لاحقاً من معايرتك: { "9": [[2,6],[1,5],[0,4,8],[3,7],[2,6]], ... } (المواضع 0..n-1 داخل كل دورة، 5 دورات)
const WZ_FIXED = {
  9: [[1],[8,0],[7],[2]],
  8: [[1]],
  7: [[1,5],[2,6],[3],[0,4]],
  6: [[1,5],[3]],
  5: [[1],[0,4],[3],[2]],
  4: [[1]],
  3: [[1],[2],[],[0]],
  2: [[1],[]],
  1: [[],[0],[],[]]
};
let WZ_CAL = {};
function wzCalLoad() { WZ_CAL = {}; } // الجدول ثابت: لا نقرأ تعديلات قديمة
function wzCalSave() { try { localStorage.setItem(WZ_CAL_KEY, JSON.stringify(WZ_CAL)); return true; } catch (e) { return false; } }
wzCalLoad();
// مواضع النظام (0..n-1) في الدورة m: الحلقة m*n+c فيها فتحة إذا ( m*n+c ) % 4 == off
function wzSysList(n, m, off) { const o = []; for (let c = 0; c < n; c++) if ((m * n + c) % 4 === off) o.push(c); return o; }
// عدد الدورات الطبيعي لكل عدد قطع: يعيد النمط بعده (9→4، 8→1، 7→4، 6→2، 5→4، 4→1، 3→4، 2→2، 1→4)
function wzRep(n) { return 4 / gcd(n, 4); }
// المواضع الفعلية للدورة m: ما عدّلته أنت، ثم الجدول الثابت، ثم النظام. بعد آخر دورة يعيد من الأولى (m % عدد الدورات).
function wzCycles(n) {
  if (WZ_CAL[n] && WZ_CAL[n].length) return WZ_CAL[n].length;
  if (WZ_FIXED[n] && WZ_FIXED[n].length) return WZ_FIXED[n].length;
  return wzRep(n);
}
function wzCycleList(n, m, off) {
  const idx = m % wzCycles(n);
  const u = WZ_CAL[n] && WZ_CAL[n][idx], f = WZ_FIXED[n] && WZ_FIXED[n][idx];
  if (Array.isArray(u)) return u;
  if (Array.isArray(f)) return f;
  return wzSysList(n, idx, off);
}
// لون الدائرة وشفافيتها (محفوظان في المتصفح)
const WZ_STYLE_KEY = "wzGapStyle_v1";
const WZ_STYLE = { color: "#0000ff", opacity: 1, enabled: true };
try { const o = JSON.parse(localStorage.getItem(WZ_STYLE_KEY) || "null"); if (o) { if (typeof o.enabled === "boolean") WZ_STYLE.enabled = o.enabled; if (/^#[0-9a-fA-F]{6}$/.test(o.color)) WZ_STYLE.color = o.color; if (typeof o.opacity === "number" && o.opacity >= 0 && o.opacity <= 1) WZ_STYLE.opacity = o.opacity; } } catch (e) {}
function wzStyleSave() { try { localStorage.setItem(WZ_STYLE_KEY, JSON.stringify(WZ_STYLE)); return true; } catch (e) { return false; } }
function wzColorNum() { return parseInt(WZ_STYLE.color.slice(1), 16); }

