const isGapRing = (ri) => ri % 4 === 2;
// القطع التي تقع عندها فتحة في الدورة m (كل دورة n حلقات)
function gapsInCycle(n, m) {
  const out = [];
  for (let c = 0; c < n; c++) if ((m * n + c) % 4 === 2) out.push(c + 1);
  return out;
}
// بعد كم دورة يعيد نفس الشكل (أو null إذا أكثر من 4)
